content.text:
                entry.hi = bits << (64 - origin - rel);
                entry.lo = 0;
            } else {
                entry.hi = 0;
                entry.lo = bits << (64 - (origin + rel - 64));
            }
            if (length < G) { if (std::getenv("SCAMP_DEBUG")) fprintf(stderr, "image.cpp:%d FAIL\n", __LINE__); return false; }
            if (!same_prefix(entry.hi, entry.lo, reg_hi, reg_lo, G)) { if (std::getenv("SCAMP_DEBUG")) fprintf(stderr, "image.cpp:%d FAIL\n", __LINE__); return false; }
            inlined.push_back(entry);
        }
        if (type == 5) {
            if (inlined[0].hi == inlined[1].hi && inlined[0].lo == inlined[1].lo &&
                inlined[0].len == inlined[1].len)
            { if (std::getenv("SCAMP_DEBUG")) fprintf(stderr, "image.cpp:%d FAIL\n", __LINE__); return false; }
    }

    // Every charged cell must belong to exactly one node.
    for (int s = 0; s < RAM_NUM; ++s)
        for (uint32_t c = 0; c < cells_[s]; ++c)
            if (owner_[s][c] < 0) { if (std::getenv("SCAMP_DEBUG")) fprintf(stderr, "image.cpp:%d FAIL\n", __LINE__); return false; }

    // The subtree sizes decide the node types.
    for (int i = static_cast<int>(nodes_.size()) - 1; i >= 0; --i) {
        VNode& node = nodes_[i];
        uint64_t total = node.local_count + node.inlined.size();
        for (int b = 0; b < 4; ++b) out[4 * i + b] = (v >> b) & 1;
    }
    return out;
}

bool MemoryImage::load(const ImageData& proposed) {
    Validator validator;
    if (!validator.validate(proposed)) { if (std::getenv("SCAMP_DEBUG")) fprintf(stderr, "image.cpp:%d FAIL\n", __LINE__); return false; }
    data_ = proposed;
    table_.clear();
    for (const auto& entry : validator.fib) table_.put(entry.hi, entry.lo, entry.len, entry.hop);
    loaded_ = true;
    return true;
